<?php
namespace App\Http\Controllers\Admin; use App\Domain\Capabilities\CapabilityRegistry; use App\Http\Controllers\Controller; use App\Models\{Capability,CapabilityBenefit,CapabilityFact,CapabilityHighlight}; use Illuminate\Http\{RedirectResponse,Request}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\Rule; use Illuminate\Validation\ValidationException; class CapabilityChildController extends Controller { private const MAP=['highlights'=>CapabilityHighlight::class,'benefits'=>CapabilityBenefit::class,'facts'=>CapabilityFact::class]; public function store(Request $request,Capability $capability,string $type):RedirectResponse{$relation=$type;$max=CapabilityRegistry::CHILDREN[$relation]??abort(404);if($capability->{$relation}()->count()>=$max)throw ValidationException::withMessages([$type=>"A maximum of $max records is allowed."]);$data=$this->data($request,$type);$data['display_order']=(int)$capability->{$relation}()->max('display_order')+1;$capability->{$relation}()->create($data);return back()->with('status','Structured item added.');} public function update(Request $request,Capability $capability,string $type,int $child):RedirectResponse{$this->owned($capability,$type,$child)->update($this->data($request,$type));return back()->with('status','Structured item saved.');} public function destroy(Capability $capability,string $type,int $child):RedirectResponse{$this->owned($capability,$type,$child)->delete();$this->normalize($capability,$type);return back();} public function move(Request $request,Capability $capability,string $type,int $child):RedirectResponse{$model=$this->owned($capability,$type,$child);$direction=$request->validate(['direction'=>['required','in:up,down']])['direction'];$class=$this->class($type);DB::transaction(function()use($model,$class,$direction,$capability,$type){$peer=$class::where('capability_id',$capability->id)->where('display_order',$direction==='up'?'<':'>',$model->display_order)->orderBy('display_order',$direction==='up'?'desc':'asc')->first();if($peer){$order=$model->display_order;$model->update(['display_order'=>$peer->display_order]);$peer->update(['display_order'=>$order]);}$this->normalize($capability,$type);});return back();} private function data(Request $request,string $type):array{return $type==='facts'?$request->validate(['label'=>['required','string','max:160'],'value'=>['required','string','max:500'],'description'=>['nullable','string','max:2000'],'is_active'=>['boolean']]):$request->validate(['title'=>['required','string','max:160'],'description'=>[$type==='highlights'?'required':'nullable','string','max:5000'],'icon'=>['nullable',Rule::in(CapabilityRegistry::ICONS)],'is_active'=>['boolean']]);} private function class(string $type):string{return self::MAP[$type]??abort(404);} private function owned(Capability $capability,string $type,int $id){return $this->class($type)::where('capability_id',$capability->id)->findOrFail($id);} private function normalize(Capability $capability,string $type):void{$this->class($type)::where('capability_id',$capability->id)->orderBy('display_order')->orderBy('id')->get()->each(fn($item,$index)=>$item->updateQuietly(['display_order'=>$index+1]));} }
